// 시뮬레이터 값과 독립 재계산 비교. 시뮬레이터 함수는 쓰지 않고 입력(CUR)과 상태(PR)만 읽어 식을 다시 계산한다
window.__vcheck = function () {
  const D = window.__dt, p = D.CUR, q = D.PR, out = [];
  const row = (name, sim, ind, unit, tol) => { const e = Math.abs(sim - ind) / Math.max(1e-9, Math.abs(ind)); out.push({ name, sim: +(+sim).toPrecision(5), ind: +(+ind).toPrecision(5), unit, err: +(e * 100).toFixed(2), ok: e <= tol }); };
  // 1) 질량 수지: 처음 액 = 탱크 + 초류 + 본류 + 진공 손실 + 충전층·응축기 홀드업 + 넘침
  { const f = q.ves.fore, m = q.ves.main, tot = q.m + f.A + f.B + m.A + m.B + (q.lost || 0) + (q.mHeld || 0) + (q.mHeldC || 0) + (q.mC1 || 0) + (q.spill.fore || 0) + (q.spill.main || 0);
    row("질량 수지 (합 / 처음)", tot, q.m0, "kg", 0.01); }
  // 2) 열 수지: 넣은 열 = 증발 + 증기 현열 + 손실 + 되데움 + 액 승온 (+ 보정)
  { const Efield = q.m * q.mix.cp * (q.Tmean - p.T0), rhs = q.Elat + q.Eout + q.Eloss + (q.Eret || 0) + Efield;
    row("열 수지 (나간 것 / 넣은 것, 보정 제외)", rhs, q.Ein, "J", 0.08);
    out.push({ name: "계산 보정 / 넣은 열", sim: +(q.Ecorr / q.Ein * 100).toFixed(2), ind: "—", unit: "%", err: "—", ok: Math.abs(q.Ecorr / q.Ein) < 0.1 }); }
  // 3) 스팀 밸브: 넣을 수 있는 열과 실효 자켓 온도
  if (p.heatMode === "steam") { const lam = (2501 - 2.37 * p.Tj) * 1000, Qcap = (p.valveChar === 'eq' ? (p.jOpen > 0 ? Math.pow(Math.max(1.01, p.valveR || 50), Math.min(1, p.jOpen) - 1) : 0) : p.jOpen) * p.mSteamMax / 3600 * lam; row("밸브가 보낼 수 있는 열 Q_cap", q.Qcap, Qcap, "W", 0.001);
    const hd = p.head === "ell" ? p.T / 4 : 0, Aw = Math.PI * p.T * Math.max(0, Math.min(p.Hj, q.h) - hd) + (p.Hj > 0 ? 1.08 * Math.PI * (p.T / 2) ** 2 : 0);
    const Uu = q.boilU ? q.boilU.U : p.U, TjE = Math.min(p.Tj, q.Tmean + Qcap / Math.max(1, Uu * Aw)); row("실효 자켓 온도", q.TjEff, TjE, "℃", 0.01); }
  // 4) 깊이별 끓는점: 클라우지우스 근사 vs 앙투안·라울로 그 압력에서 바로 푼 끓는점
  { const sb = [p.A, p.B], xs = [q.x[0], q.x[1]], s0 = xs[0] + xs[1]; const ps = (s, T) => s.antoine ? 10 ** (s.antoine.A - s.antoine.B / (s.antoine.C + T)) : 760 * Math.exp(-s.hvap * s.MW / 8.314 * (1 / (T + 273.15) - 1 / (s.Tb + 273.15)));
    const bub = (P) => { let lo = -100, hi = 600; for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; const v = (xs[0] * ps(sb[0], m) + xs[1] * ps(sb[1], m)) / s0; v > P ? (hi = m) : (lo = m); } return (lo + hi) / 2; };
    const tbD = (d) => { const P0 = q.Pstill, Pz = P0 + q.mix.rho * 9.81 * d / 133.322, T0 = q.Tbub + 273.15; return 1 / (1 / T0 - 8.314 / q.Lmol * Math.log(Pz / P0)) - 273.15; };
    for (const d of [0.01, 0.1, 0.3]) row(`깊이 ${d * 100} cm 끓는점 (근사 vs 직접)`, tbD(d), bub(q.Pstill + q.mix.rho * 9.81 * d / 133.322), "℃", 0.02); }
  // 5) 자연대류 액 쪽 전열계수
  if (p.Ucalc) { const nu = q.mix.mu / q.mix.rho, Pr = q.mix.cp * q.mix.mu / p.kL, Ra = 9.81 * 1e-3 * 10 / (nu * nu) * Pr; row("자연대류 h (0.13·Ra^1/3·k)", p.Ucalc.hNc, 0.13 * Math.cbrt(Ra) * p.kL, "W/m²K", 0.05); }
  // 6) 배관 상당 길이
  row("배관 상당 길이", p.Lpipe, p.Lstr + p.Dpipe * (30 * p.nElb + 60 * p.nTee + 8 * p.nVg + 340 * p.nVgl), "m", 0.001);
  // 7) 음속 한계: 0.95 ρ a A (응축기 압력, 증기 분자량·온도)
  if (q.Wmax && Number.isFinite(q.Wmax) && q.Pcond > 0) { const Mv = (q.y[0] * p.A.MW + q.y[1] * p.B.MW) / 1000, Tv = q.Tbub + 273.15, N = Math.max(3, Mv * 1000 / 5.5), g = 1 + 2 / (3 + 3 * N - 6), a = Math.sqrt(g * 8.314 * Tv / Mv), rho = q.Pcond * 133.322 * Mv / (8.314 * Tv), A = Math.PI * p.Dpipe * p.Dpipe / 4;
    row("음속 한계 유량", q.Wmax, 0.95 * rho * a * A * 3600, "kg/h", 0.05); }
  // 8) 과냉 환류 보정
  if (q.T1out != null && q.Tsat != null && q.lam > 0 && q.Reff < 1000) row("과냉 보정 cp·ΔT/λ", q.subR, Math.max(0, Math.min(0.5, q.mix.cp * (q.Tsat - q.T1out) / q.lam)), "—", 0.02);
  // 9) 범람비 → 효율
  if (q.flood != null) { const ph = q.flood, fE = ph <= 0.85 ? 1 : Math.max(0.15, 1 - 0.85 * (ph - 0.85) / 0.35); row("범람 효율 f_E", q.fE, fE, "—", 0.001); }
  // 10) 스팀 포화 온도 (압력 입력 시)
  if (p.Psteam != null) { const Pmm = (p.Psteam + 1.01325) * 750.06; let lo = 0, hi = 250; for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; const v = m < 100 ? 10 ** (8.07131 - 1730.63 / (233.426 + m)) : 10 ** (8.14019 - 1810.94 / (244.485 + m)); v > Pmm ? (hi = m) : (lo = m); } row("스팀 포화 온도", p.Tj, (lo + hi) / 2, "℃", 0.002); }
  if (D.flow1D) D.flow1D();   // 1차원 값을 지금 상태로 다시 계산해 비교한다
  // 11) 배관 입구 압력: 등온 압축성(가속 항 포함) P1² − P2² = K·(f·L/D + 2·ln(P1/P2))를 따로 풀어 비교
  if (q.p1d && q.p1d.W > 0 && q.p1d.K > 0) { const pp = q.p1d, g = (P1) => P1 * P1 - pp.P2 * pp.P2 - pp.K * (pp.f * pp.L / pp.D + 2 * Math.log(P1 / pp.P2));
    let lo = pp.P2, hi = pp.P2 * 20 + 50; for (let i = 0; i < 80; i++) { const m = (lo + hi) / 2; g(m) > 0 ? (hi = m) : (lo = m); }
    row("배관 입구 압력 (등온 파노, 독립)", pp.P1, (lo + hi) / 2, "mmHg", 0.005);
    if (D.F1D && D.F1D.pipe) { const P1d = D.F1D.pipe.P; row("배관 1차원 출구 압력 = P_exit", P1d[P1d.length - 1], pp.P2, "mmHg", 0.005); } }
  // 12) 응축기 1차원: 공기를 고르게 두고 48칸으로 나누면 NTU-ε 해와 같아야 한다 (칸 나눔 오차만 남음)
  if (p.UA1 > 0 && q.lam > 0 && q.vdot > 1 && D.VLV.C1) { const Cw = p.mcw / 3600 * 4182, Tsat = q.Tsat != null ? q.Tsat : q.Thead, Ql = (q.vpass != null ? q.vpass : q.vdot) / 3600 * q.lam * (1 - p.f2), fnc = q.fNC || 1;
    const N = 48; const sim = (To) => { let Tw = To, V = 1, Q = 0; for (let i = 0; i < N; i++) { let qq = p.UA1 * fnc / N * Math.max(0, Tsat - Tw); if (qq > V * Ql) qq = V * Ql; V -= qq / Ql; Q += qq; Tw -= qq / Cw; } return { Tw, Q }; };
    let lo = p.Tcw, hi = Tsat, r; for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; r = sim(m); r.Tw > p.Tcw ? (hi = m) : (lo = m); } r = sim((lo + hi) / 2);
    const eps = 1 - Math.exp(-p.UA1 * fnc / Cw), Qa = Math.min(Ql, eps * Cw * Math.max(0, Tsat - p.Tcw));
    row("응축기 1차원 48칸 합 vs NTU-ε", r.Q, Qa, "W", 0.02); }
  return out;
};
;'loaded'
